package de.raindancer.modules.shops.market;

import java.util.List;

/**
 * What the market world is built of, block by block: cobbled streets with sidewalks and lamp posts, a striped market
 * stall on every plot until its owner builds their own, hedges between the plots, half-timbered houses closing the
 * blocks, and the market square with its fountain. Pure: a block state for a position, the same every time — a chunk
 * is generated by asking for each of its blocks, so nothing ever depends on which chunk came first.
 *
 * <p>States are Minecraft's own strings ({@code minecraft:spruce_stairs[facing=north,half=bottom]}); the generator
 * turns them into block data once each. {@code null} is air.
 */
public final class MarketDesigns {

    /** The top of the ground: streets and plots are this high, everything built stands on it. */
    public static final int GROUND = 64;

    private static final String AIR = null;
    private static final List<String> STRIPES = List.of("red", "blue", "green", "yellow", "orange", "purple", "cyan",
            "lime", "magenta", "light_blue", "pink", "brown");
    private static final List<String> FLOWERS = List.of("poppy", "dandelion", "cornflower", "oxeye_daisy", "allium",
            "azure_bluet");
    private static final List<String> PLASTER = List.of("calcite", "white_terracotta", "smooth_sandstone",
            "mushroom_stem", "pale_oak_planks", "calcite");
    private static final List<String> BEAMS = List.of("dark_oak_log", "spruce_log", "stripped_dark_oak_log",
            "dark_oak_log");
    private static final List<String> ROOFS = List.of("deepslate_tile", "dark_oak", "spruce", "brick",
            "deepslate_tile", "mud_brick");
    private static final List<String> BASES = List.of("stone_bricks", "cobblestone", "mossy_stone_bricks",
            "tuff_bricks");
    /** Ways to split a house row (25 blocks) into houses of odd widths, so each has a ridge in its middle. */
    private static final List<int[]> ROWS = List.of(new int[]{7, 11, 7}, new int[]{9, 7, 9}, new int[]{11, 7, 7},
            new int[]{7, 7, 11}, new int[]{5, 9, 11}, new int[]{11, 9, 5}, new int[]{9, 9, 7});

    private final MarketLayout layout;
    private final Prefabs prefabs;

    public MarketDesigns(MarketLayout layout) {
        this(layout, Prefabs.NONE);
    }

    /** @param prefabs the owner's own stalls and house fronts, used where they fit; the rest is built as usual */
    public MarketDesigns(MarketLayout layout, Prefabs prefabs) {
        this.layout = layout;
        this.prefabs = prefabs;
    }

    public MarketLayout layout() {
        return layout;
    }

    /** The highest y anything stands at — the generator need not ask above it. */
    public static int highest() {
        return GROUND + 22;
    }

    public String stateAt(int x, int y, int z) {
        if (y < GROUND - 3) {
            return "minecraft:stone";
        }
        MarketLayout.Cell cell = layout.at(x, z);
        return switch (cell.kind()) {
            case STREET -> street(cell, x, y, z);
            case PLOT -> plot(cell, x, y, z);
            case HEDGE -> hedge(cell, x, y, z);
            case HOUSES -> houses(cell, x, y, z);
            case SQUARE -> square(cell, x, y, z);
        };
    }

    // ------------------------------------------------------------------ streets

    private String street(MarketLayout.Cell cell, int x, int y, int z) {
        if (y < GROUND) {
            return y == GROUND - 1 ? "minecraft:gravel" : "minecraft:stone";
        }
        if (y == GROUND) {
            if (cell.crossing() || !cell.sidewalk()) {
                return cobbles(x, z);
            }
            boolean curb = cell.u() == MarketLayout.SIDEWALK - 1 || cell.u() == MarketLayout.STREET - MarketLayout.SIDEWALK;
            if (curb) {
                double roll = noise(x, z, 11);
                return roll < 0.06 ? "minecraft:cracked_stone_bricks" : roll < 0.12 ? "minecraft:mossy_stone_bricks"
                        : "minecraft:stone_bricks";
            }
            return noise(x, z, 12) < 0.12 ? "minecraft:andesite" : "minecraft:polished_andesite";
        }
        if (cell.crossing()) {
            return AIR;
        }
        return lamp(cell, y);
    }

    /** A road of mixed stones, worn smooth here and there. */
    private static String cobbles(int x, int z) {
        double roll = noise(x, z, 7);
        if (roll < 0.42) {
            return "minecraft:cobblestone";
        }
        if (roll < 0.64) {
            return "minecraft:andesite";
        }
        if (roll < 0.80) {
            return "minecraft:stone";
        }
        if (roll < 0.92) {
            return "minecraft:tuff";
        }
        return "minecraft:mossy_cobblestone";
    }

    /**
     * A lamp post every twelve blocks on the outer edge of each sidewalk: a stone base, a spruce post, an arm reaching
     * over the sidewalk and a lantern hanging from it.
     */
    private static String lamp(MarketLayout.Cell cell, int y) {
        int u = cell.u();
        boolean outer = u == 0 || u == MarketLayout.STREET - 1;
        boolean arm = u == 1 || u == MarketLayout.STREET - 2;
        if (Math.floorMod(cell.v(), 12) != 6 || !(outer || arm)) {
            return AIR;
        }
        // Which way across the street is "towards the road" from the post, as a block face.
        boolean low = u <= 1;
        String across = cell.facing() == MarketLayout.Facing.EAST ? (low ? "south" : "north") : (low ? "east" : "west");
        String back = opposite(across);
        int h = y - GROUND;
        if (outer) {
            return switch (h) {
                case 1 -> "minecraft:stone_brick_wall[up=true]";
                case 2, 3 -> "minecraft:spruce_fence";
                case 4 -> "minecraft:spruce_fence[" + across + "=true]";
                case 5 -> "minecraft:spruce_trapdoor[half=bottom]";
                default -> AIR;
            };
        }
        return switch (h) {
            case 4 -> "minecraft:spruce_fence[" + back + "=true]";
            case 3 -> "minecraft:lantern[hanging=true]";
            default -> AIR;
        };
    }

    // ------------------------------------------------------------------ plots

    /**
     * An unbuilt plot: grass, a few flowers at the back, and a market stall at the front — a plank floor, four posts,
     * a counter with barrels, crates at the back and a striped canopy with a wooden valance and two lanterns.
     */
    private String plot(MarketLayout.Cell cell, int x, int y, int z) {
        if (!prefabs.stalls().isEmpty()) {
            return ownStall(cell, y);
        }
        int u = cell.u();
        int v = cell.v();
        boolean floor = u >= 2 && u <= 9 && v >= 1 && v <= 5;
        if (y < GROUND) {
            return "minecraft:dirt";
        }
        if (y == GROUND) {
            return floor ? "minecraft:spruce_planks" : "minecraft:grass_block";
        }
        MarketLayout.Plot plot = cell.plot();
        String front = plot.facing() == MarketLayout.Facing.NORTH ? "north" : "south";
        String backward = opposite(front);
        int h = y - GROUND;
        boolean post = (u == 2 || u == 9) && (v == 1 || v == 5);
        if (post && h <= 3) {
            return "minecraft:stripped_spruce_log[axis=y]";
        }
        if (h == 1) {
            if (v == 1 && u >= 3 && u <= 8) {
                return u == 3 || u == 8 ? "minecraft:barrel[facing=up]" : "minecraft:spruce_slab[type=top]";
            }
            if (v == 5 && (u == 3 || u == 4 || u == 7 || u == 8)) {
                return "minecraft:barrel[facing=" + front + "]";
            }
            if ((u == 2 || u == 9) && v >= 2 && v <= 4) {
                return "minecraft:spruce_fence[north=true,south=true]";
            }
            if (!floor && v >= 7 && noise(x, z, 21) < 0.06) {
                return "minecraft:" + FLOWERS.get(pick(x, z, 22, FLOWERS.size()));
            }
            if (!floor && v >= 7 && noise(x, z, 23) < 0.10) {
                return "minecraft:short_grass";
            }
            return AIR;
        }
        if (h == 2 && v == 5 && (u == 3 || u == 8)) {
            return "minecraft:barrel[facing=up]";
        }
        String colour = STRIPES.get(pick(plot.bx() * 31 + plot.col(), plot.bz() * 17 + plot.row(), 5,
                STRIPES.size()));
        String stripe = "minecraft:" + (u % 2 == 0 ? colour : "white") + "_wool";
        boolean under = u >= 1 && u <= 10;
        if (stallVariant(plot) == 1) {
            // A tent: a striped gable roof, eaves front and back, the ridge over the middle of the stall.
            if (under && ((h == 3 && (v == 0 || v == 6)) || (h == 4 && (v == 1 || v == 5))
                    || (h == 5 && v >= 2 && v <= 4))) {
                return stripe;
            }
            if (h == 4 && (u == 3 || u == 8) && v == 3) {
                return "minecraft:lantern[hanging=true]";
            }
            return AIR;
        }
        // An awning: flat and striped, a scalloped wooden valance along its front, lanterns under it.
        boolean canopy = under && v >= 0 && v <= 6;
        if (h == 4 && canopy) {
            return stripe;
        }
        if (h == 3 && canopy) {
            if ((u == 3 || u == 8) && v == 3) {
                return "minecraft:lantern[hanging=true]";
            }
            if (v == 0 && u % 2 == 1) {
                return "minecraft:spruce_trapdoor[open=true,half=top,facing=" + backward + "]";
            }
        }
        return AIR;
    }

    /** An unbuilt plot with one of the owner's own stalls on it, centred across the plot, its front at the street. */
    private String ownStall(MarketLayout.Cell cell, int y) {
        if (y < GROUND) {
            return "minecraft:dirt";
        }
        MarketLayout.Plot plot = cell.plot();
        de.raindancer.core.world.build.Schematic stall = prefabs.stalls().get(pick(plot.bx() * 7 + plot.col(),
                plot.bz() * 11 + plot.row(), 8, prefabs.stalls().size()));
        int offset = (MarketLayout.PLOT - stall.width()) / 2;
        boolean north = plot.facing() == MarketLayout.Facing.NORTH;
        int sx = north ? cell.u() - offset : (MarketLayout.PLOT - 1 - cell.u()) - offset;
        String state = stall.stateAt(sx, y - GROUND, cell.v());
        boolean air = state == null || state.equals("minecraft:air");
        if (air) {
            return y == GROUND ? "minecraft:grass_block" : AIR;
        }
        return north ? state : Prefabs.turned(state);
    }

    /** Which stall an unbuilt plot gets: 0 an awning, 1 a tent — scattered, the same every time. */
    public static int stallVariant(MarketLayout.Plot plot) {
        return pick(plot.bx() * 7 + plot.col(), plot.bz() * 11 + plot.row(), 6, 2);
    }

    // ------------------------------------------------------------------ hedges

    /** Azalea hedges between the plots — two high along the backs, one high between neighbours, a lit post in front. */
    private String hedge(MarketLayout.Cell cell, int x, int y, int z) {
        if (y < GROUND) {
            return "minecraft:dirt";
        }
        if (y == GROUND) {
            return "minecraft:grass_block";
        }
        int h = y - GROUND;
        boolean backs = cell.v() == MarketLayout.PLOT;
        boolean atTheStreet = !backs && (cell.v() == 0 || cell.v() == 2 * MarketLayout.PLOT);
        if (atTheStreet) {
            return switch (h) {
                case 1 -> "minecraft:mossy_cobblestone_wall[up=true]";
                case 2 -> "minecraft:lantern[hanging=false]";
                default -> AIR;
            };
        }
        if (h == 1 || (backs && h == 2)) {
            return noise(x, z + h * 7, 31) < 0.25 ? "minecraft:flowering_azalea_leaves[persistent=true]"
                    : "minecraft:azalea_leaves[persistent=true]";
        }
        return AIR;
    }

    // ------------------------------------------------------------------ houses

    /** One house of a row: where it starts along the row, how wide it is, and what it is built of. */
    private record House(int start, int width, int floors, String plaster, String beam, String roof, String base,
                         boolean chimney) {
    }

    /** A row's length, along the cross street. */
    private static final int ROW_LENGTH = MarketLayout.PLOT * 2 + MarketLayout.HEDGE;

    /**
     * One of the owner's house fronts, where the row has one: "" for air in it, null where the row is built as usual
     * (what is left of a row no front fits into). Along the east rows they run the other way and are turned round.
     */
    private String ownHouse(MarketLayout.Cell cell, int y) {
        boolean west = cell.facing() == MarketLayout.Facing.WEST;
        int along = west ? cell.v() : ROW_LENGTH - 1 - cell.v();
        int seedX = cell.bx() * 2 + (west ? 0 : 1);
        int start = 0;
        int index = 0;
        while (start < ROW_LENGTH) {
            int left = ROW_LENGTH - start;
            List<de.raindancer.core.world.build.Schematic> fitting = prefabs.houses().stream()
                    .filter(house -> house.length() <= left).toList();
            if (fitting.isEmpty()) {
                return null;
            }
            de.raindancer.core.world.build.Schematic house = fitting.get(pick(seedX * 13 + index, cell.bz() * 7,
                    48, fitting.size()));
            if (along < start + house.length()) {
                String state = house.stateAt(cell.u(), y - GROUND, along - start);
                boolean air = state == null || state.equals("minecraft:air");
                if (air) {
                    return y == GROUND ? "minecraft:grass_block" : "";
                }
                return west ? state : Prefabs.turned(state);
            }
            start += house.length();
            index++;
        }
        return null;
    }

    /** Where the owner's fronts along a row end (its length when they fill it), counted from the row's start. */
    private int ownFrontsEnd(MarketLayout.Cell cell) {
        boolean west = cell.facing() == MarketLayout.Facing.WEST;
        int seedX = cell.bx() * 2 + (west ? 0 : 1);
        int start = 0;
        int index = 0;
        while (start < ROW_LENGTH) {
            int left = ROW_LENGTH - start;
            List<de.raindancer.core.world.build.Schematic> fitting = prefabs.houses().stream()
                    .filter(house -> house.length() <= left).toList();
            if (fitting.isEmpty()) {
                return start;
            }
            start += fitting.get(pick(seedX * 13 + index, cell.bz() * 7, 48, fitting.size())).length();
            index++;
        }
        return ROW_LENGTH;
    }

    /** What is left of a row after the owner's fronts: one house of the usual kind, as wide as the gap. */
    private House restOfRow(MarketLayout.Cell cell) {
        boolean west = cell.facing() == MarketLayout.Facing.WEST;
        int end = ownFrontsEnd(cell);
        int width = ROW_LENGTH - end;
        int sx = (cell.bx() * 2 + (west ? 0 : 1)) * 7 + 5;
        int sz = cell.bz() * 13 + 5;
        return new House(west ? end : 0, width, 2, PLASTER.get(pick(sx, sz, 43, PLASTER.size())),
                BEAMS.get(pick(sx, sz, 44, BEAMS.size())), ROOFS.get(pick(sx, sz, 45, ROOFS.size())),
                BASES.get(pick(sx, sz, 46, BASES.size())), false);
    }

    private House houseAt(MarketLayout.Cell cell) {
        int seedX = cell.bx() * 2 + (cell.facing() == MarketLayout.Facing.WEST ? 0 : 1);
        int[] widths = ROWS.get(pick(seedX, cell.bz(), 41, ROWS.size()));
        int start = 0;
        for (int index = 0; index < widths.length; index++) {
            if (cell.v() < start + widths[index] || index == widths.length - 1) {
                int sx = seedX * 7 + index;
                int sz = cell.bz() * 13 + index;
                return new House(start, widths[index], noise(sx, sz, 42) < 0.3 ? 3 : 2,
                        PLASTER.get(pick(sx, sz, 43, PLASTER.size())), BEAMS.get(pick(sx, sz, 44, BEAMS.size())),
                        ROOFS.get(pick(sx, sz, 45, ROOFS.size())), BASES.get(pick(sx, sz, 46, BASES.size())),
                        noise(sx, sz, 47) < 0.45);
            }
            start += widths[index];
        }
        throw new IllegalStateException("a house row is 25 long");
    }

    /**
     * Half-timbered houses, gable to the street: a stone ground floor with a door and two windows, timbered plaster
     * above with windows on every floor, a steep roof, sometimes a chimney with smoke. Hollow and lit inside, so the
     * windows glow at night.
     */
    private String houses(MarketLayout.Cell cell, int x, int y, int z) {
        if (y < GROUND) {
            return "minecraft:stone";
        }
        if (!prefabs.houses().isEmpty()) {
            String own = ownHouse(cell, y);
            if (own != null) {
                return own.isEmpty() ? AIR : own;
            }
        }
        House house = prefabs.houses().isEmpty() ? houseAt(cell) : restOfRow(cell);
        int w = cell.v() - house.start();
        int d = cell.u();
        int width = house.width();
        int depth = MarketLayout.HOUSES;
        int mid = (width - 1) / 2;
        String street = cell.facing() == MarketLayout.Facing.WEST ? "west" : "east";
        boolean front = d == 0;
        boolean back = d == depth - 1;
        boolean side = w == 0 || w == width - 1;
        boolean wall = front || back || side;
        int h = y - GROUND;
        int wallTop = house.floors() * 4 + 1;
        if (h == 0) {
            return wall ? "minecraft:" + house.base() : "minecraft:spruce_planks";
        }
        if (h <= wallTop) {
            if (!wall) {
                return inside(house, w, d, h, mid);
            }
            return facade(house, w, d, h, mid, wallTop, front, back, side, street);
        }
        return roof(house, w, d, h - wallTop, mid, width, front, back);
    }

    private String inside(House house, int w, int d, int h, int mid) {
        if (h % 4 == 0 && h > 0) {
            return "minecraft:spruce_planks";
        }
        // Hanging just behind the windows, front and back, so they glow from the street at night.
        if (h % 4 == 3 && (d == 1 || d == MarketLayout.HOUSES - 2) && (w == mid - 2 || w == mid + 2 || w == mid)
                && w > 0 && w < house.width() - 1) {
            return "minecraft:lantern[hanging=true]";
        }
        if (house.chimney() && w == 1 && d == 4) {
            return "minecraft:bricks";
        }
        return AIR;
    }

    private String facade(House house, int w, int d, int h, int mid, int wallTop, boolean front, boolean back,
                          boolean side, String street) {
        String beamAlong = "minecraft:" + house.beam() + "[axis=" + (front || back ? "z" : "x") + "]";
        String post = "minecraft:" + house.beam() + "[axis=y]";
        boolean corner = (front || back) && side;
        if (h <= 4) {
            if (corner) {
                return post;
            }
            if (front && w == mid && h <= 2) {
                return "minecraft:spruce_door[facing=" + street + ",half=" + (h == 1 ? "lower" : "upper")
                        + ",hinge=left,open=false]";
            }
            if (front && h == 3 && w == mid) {
                return beamAlong;
            }
            if ((front || back) && (h == 2 || h == 3) && (w == mid - 2 || w == mid + 2) && !side) {
                return "minecraft:glass_pane[north=true,south=true]";
            }
            return "minecraft:" + house.base();
        }
        int level = (h - 1) % 4;
        if (level == 0 || h == wallTop) {
            return beamAlong;
        }
        if (corner || ((front || back) && (w == mid - 1 || w == mid + 1) && house.width() >= 7)) {
            return post;
        }
        if ((front || back) && level >= 1 && level <= 2 && (w == mid || ((w == mid - 3 || w == mid + 3) && !side))) {
            return "minecraft:glass_pane[north=true,south=true]";
        }
        return "minecraft:" + house.plaster();
    }

    /** The roof above the walls: stairs climbing from both eaves to a ridge over the middle, gables at both ends. */
    private String roof(House house, int w, int d, int above, int mid, int width, boolean front, boolean back) {
        int level = above - 1;
        if (house.chimney() && w == 1 && d == 4 && level <= mid + 1) {
            return level == mid + 1 ? "minecraft:campfire[lit=true,signal_fire=false]" : "minecraft:bricks";
        }
        if (level > mid) {
            return AIR;
        }
        String stairs = "minecraft:" + house.roof() + "_stairs[half=bottom,shape=straight,facing=";
        if (level == mid && w == mid) {
            return "minecraft:" + house.roof() + "_slab[type=bottom]";
        }
        if (w == level) {
            return stairs + "south]";
        }
        if (w == width - 1 - level) {
            return stairs + "north]";
        }
        if (w > level && w < width - 1 - level && (front || back)) {
            if (w == mid) {
                return level == mid - 1 && mid >= 3 ? "minecraft:glass_pane[north=true,south=true]"
                        : "minecraft:" + house.beam() + "[axis=y]";
            }
            return "minecraft:" + house.plaster();
        }
        return AIR;
    }

    // ------------------------------------------------------------------ the square

    /**
     * The market square: rings of polished andesite in stone bricks around a fountain, four trees in grass beds,
     * four benches facing the fountain and four lamp posts.
     */
    private String square(MarketLayout.Cell cell, int x, int y, int z) {
        int u = cell.u();
        int v = cell.v();
        double cx = layout.spawnX();
        double cz = layout.spawnZ();
        double r = Math.hypot(u - cx, v - cz);
        int h = y - GROUND;
        if (r <= 4.6) {
            return fountain(r, h);
        }
        int[][] trees = {{10, 6}, {54, 6}, {10, 18}, {54, 18}};
        for (int[] tree : trees) {
            int du = u - tree[0];
            int dv = v - tree[1];
            String part = tree(du, dv, h);
            if (part != null || (Math.abs(du) <= 2 && Math.abs(dv) <= 2)) {
                return part;
            }
        }
        if (h < 0) {
            return "minecraft:stone";
        }
        if (h == 0) {
            if (u == 0 || u == 64 || v == 0 || v == 24) {
                return "minecraft:polished_andesite";
            }
            if (Math.floorMod((int) Math.round(r), 4) == 0) {
                return "minecraft:polished_andesite";
            }
            return noise(x, z, 51) < 0.07 ? "minecraft:cracked_stone_bricks" : "minecraft:stone_bricks";
        }
        String bench = bench(u, v, h, (int) cx, (int) cz);
        if (bench != null) {
            return bench;
        }
        int[][] lamps = {{24, 5}, {40, 5}, {24, 19}, {40, 19}};
        for (int[] lamp : lamps) {
            if (u == lamp[0] && v == lamp[1]) {
                return switch (h) {
                    case 1 -> "minecraft:stone_brick_wall[up=true]";
                    case 2, 3 -> "minecraft:spruce_fence";
                    case 4 -> "minecraft:lantern[hanging=false]";
                    default -> AIR;
                };
            }
        }
        return AIR;
    }

    private static String fountain(double r, int h) {
        if (h < -1) {
            return "minecraft:stone";
        }
        if (r > 3.6) {
            return switch (h) {
                case -1, 0 -> "minecraft:stone_bricks";
                case 1 -> "minecraft:stone_brick_slab[type=bottom]";
                default -> AIR;
            };
        }
        if (r < 0.5) {
            return switch (h) {
                case -1, 0 -> "minecraft:stone_bricks";
                case 1 -> "minecraft:chiseled_stone_bricks";
                case 2 -> "minecraft:stone_brick_wall[up=true]";
                case 3 -> "minecraft:chiseled_stone_bricks";
                case 4 -> "minecraft:lantern[hanging=false]";
                default -> AIR;
            };
        }
        if (r <= 1.5 && h == 1) {
            return "minecraft:stone_brick_slab[type=bottom,waterlogged=true]";
        }
        return switch (h) {
            case -1 -> "minecraft:stone_bricks";
            case 0 -> "minecraft:water";
            default -> AIR;
        };
    }

    /** A small oak: a grass bed, a four-high trunk, a round crown. Null where the tree is not. */
    private static String tree(int du, int dv, int h) {
        if (Math.abs(du) > 3 || Math.abs(dv) > 3) {
            return null;
        }
        if (h == 0 && Math.abs(du) <= 2 && Math.abs(dv) <= 2) {
            return Math.abs(du) == 2 || Math.abs(dv) == 2 ? "minecraft:mud_bricks" : "minecraft:grass_block";
        }
        if (h < 0) {
            return Math.abs(du) <= 2 && Math.abs(dv) <= 2 ? "minecraft:dirt" : null;
        }
        if (du == 0 && dv == 0 && h >= 1 && h <= 5) {
            return "minecraft:oak_log[axis=y]";
        }
        double crown = Math.sqrt(du * du + dv * dv + (h - 6.0) * (h - 6.0) * 1.4);
        if (h >= 4 && crown <= 2.8) {
            return "minecraft:oak_leaves[persistent=true]";
        }
        return null;
    }

    private static String bench(int u, int v, int h, int cx, int cz) {
        if (h != 1) {
            return null;
        }
        if (v >= cz - 1 && v <= cz + 1) {
            if (u == cx - 9) {
                return "minecraft:spruce_stairs[facing=west,half=bottom]";
            }
            if (u == cx + 9) {
                return "minecraft:spruce_stairs[facing=east,half=bottom]";
            }
        }
        if (u >= cx - 1 && u <= cx + 1) {
            if (v == cz - 7) {
                return "minecraft:spruce_stairs[facing=north,half=bottom]";
            }
            if (v == cz + 7) {
                return "minecraft:spruce_stairs[facing=south,half=bottom]";
            }
        }
        return null;
    }

    // ------------------------------------------------------------------ the rest

    private static String opposite(String face) {
        return switch (face) {
            case "north" -> "south";
            case "south" -> "north";
            case "east" -> "west";
            default -> "east";
        };
    }

    /** A number in [0, 1) for a column and a purpose, the same every time — scattered, not striped. */
    static double noise(int x, int z, int salt) {
        long h = x * 0x9E3779B97F4A7C15L ^ z * 0xC2B2AE3D27D4EB4FL ^ salt * 0x165667B19E3779F9L;
        h ^= h >>> 33;
        h *= 0xFF51AFD7ED558CCDL;
        h ^= h >>> 33;
        h *= 0xC4CEB9FE1A85EC53L;
        h ^= h >>> 33;
        return (h >>> 11) * 0x1.0p-53;
    }

    private static int pick(int x, int z, int salt, int choices) {
        return (int) (noise(x, z, salt) * choices);
    }
}
